using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class LabApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LabIdentity/";const string A="Assets/Afrer_Seconds/05.Model/",P=A+"Props/B4/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");return s;}
 static Transform Find(string id){if(!GlobalObjectId.TryParse(id,out var g))throw new Exception(id);return GlobalObjectId.GlobalObjectIdentifierToObjectSlow(g) as Transform;}
 public static object Import(){Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=new Dictionary<string,Material>();foreach(var f in Directory.GetFiles(A+"Environment/B4/Materials","*.mat").Concat(Directory.GetFiles(P+"Materials","*.mat"))){var m=AssetDatabase.LoadAssetAtPath<Material>(f.Replace('\\','/'));if(m)mats[m.name]=m;}
 foreach(string k in new[]{"Coat","Steel"}){string n="LB_"+k,mp=P+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!m){m=new Material(mats["B4O_"+k]){name=n};AssetDatabase.CreateAsset(m,mp);}m.SetColor("_BaseColor",k=="Coat"?new Color(.52f,.55f,.54f):new Color(.36f,.39f,.40f));m.SetFloat("_Metallic",k=="Coat"?.12f:.85f);m.SetFloat("_Smoothness",k=="Coat"?.29f:.42f);mats[n]=m;EditorUtility.SetDirty(m);}
 var texNames=Enumerable.Range(1,6).Select(i=>"LB_Record_"+i.ToString("00")).Concat(Enumerable.Range(43,8).Select(i=>"LB_Display_"+i.ToString("00"))).Concat(new[]{"LB_EquipmentLabels"});
 foreach(string n in texNames){string tx=P+"Textures/"+n+".png",key=n=="LB_EquipmentLabels"?"LB_Labels":n,mp=P+"Materials/"+key+".mat";var ti=(TextureImporter)AssetImporter.GetAtPath(tx);ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.wrapMode=TextureWrapMode.Clamp;ti.maxTextureSize=n.Contains("Display")?1024:2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.anisoLevel=8;ti.SaveAndReimport();var m=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=key};AssetDatabase.CreateAsset(m,mp);}var t=AssetDatabase.LoadAssetAtPath<Texture2D>(tx);m.SetTexture("_BaseMap",t);m.SetColor("_BaseColor",Color.white);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",n.Contains("Display")?.24f:.12f);if(n.Contains("Display")){m.SetTexture("_EmissionMap",t);m.SetColor("_EmissionColor",new Color(.20f,.20f,.20f));m.EnableKeyword("_EMISSION");}mats[key]=m;EditorUtility.SetDirty(m);}
 var manifest=JObject.Parse(File.ReadAllText(H+"models.json"));var result=new List<object>();
 foreach(var j in manifest.Properties())foreach(string n in (int)j.Value["collisionTriangles"]>0?new[]{j.Name,j.Name.Replace("LB_","LC_")}:new[]{j.Name}){string path=P+n+".fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();var g=AssetDatabase.LoadAssetAtPath<GameObject>(path);var f=g.GetComponentsInChildren<MeshFilter>().Single();var rr=f.GetComponent<Renderer>();int bad=0;var verts=f.sharedMesh.vertices;var tr=f.sharedMesh.triangles;for(int i=0;i<tr.Length;i+=3)if(Vector3.Cross(verts[tr[i+1]]-verts[tr[i]],verts[tr[i+2]]-verts[tr[i]]).sqrMagnitude<1e-16f)bad++;result.Add(new{name=n,triangles=tr.Length/3,degenerate=bad,size=V(f.sharedMesh.bounds.size),center=V(f.sharedMesh.bounds.center),materials=rr.sharedMaterials.Select(m=>m?m.name:"NULL")});}
 AssetDatabase.SaveAssets();File.WriteAllText(H+"catalog.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{models=result.Count,bad=result.Count(x=>(int)x.GetType().GetProperty("degenerate").GetValue(x)>0)};}
 public static object Run(){var s=Check();var plan=JObject.Parse(File.ReadAllText(H+"changes.json"));var records=new List<object>();foreach(var p in plan["replacements"]){var t=Find((string)p["id"]);if(!t)throw new Exception("Missing target "+p["oldName"]);var mf=t.GetComponent<MeshFilter>();string path=P+(string)p["model"]+".fbx";var src=AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<MeshFilter>().Single();mf.sharedMesh=src.sharedMesh;var mr=t.GetComponent<MeshRenderer>();mr.sharedMaterials=src.GetComponent<MeshRenderer>().sharedMaterials;if((string)p["model"]=="LB_RecordKit"){int k=t.name.Contains("_E01_")?6:t.name.Contains("_E02_")?5:t.name.Contains("_N01_")?3:4;var mm=mr.sharedMaterials;for(int i=0;i<mm.Length;i++)if(mm[i]&&mm[i].name=="LB_Record_01")mm[i]=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/LB_Record_"+k.ToString("00")+".mat");mr.sharedMaterials=mm;}t.name=(string)p["name"];if((bool)p["collision"]){foreach(var old in t.GetComponents<Collider>()){old.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(old);}var mc=t.GetComponent<MeshCollider>();if(!mc)mc=t.gameObject.AddComponent<MeshCollider>();mc.sharedMesh=AssetDatabase.LoadAssetAtPath<GameObject>(path.Replace("/LB_","/LC_")).GetComponentsInChildren<MeshFilter>().Single().sharedMesh;mc.convex=false;mc.isTrigger=false;mc.enabled=true;PrefabUtility.RecordPrefabInstancePropertyModifications(mc);}foreach(var ob in new UnityEngine.Object[]{t,t.gameObject,mf,mr})PrefabUtility.RecordPrefabInstancePropertyModifications(ob);records.Add(new{name=t.name,id=(string)p["id"],model=(string)p["model"],size=V(mf.sharedMesh.bounds.size)});}
 foreach(var id in plan["disable"]){var t=Find((string)id);if(!t)throw new Exception("Missing disable target");t.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.WriteAllText(H+"applied.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{replaced=records.Count,disabled=plan["disable"].Count(),scene=s.path};}
}
